examples.template:
VStack(alignment: .leading, spacing: 12) {
    MonarchOtpPinInput({{label}}, text: $code, length: {{length}}, helper: {{description}})
    MonarchButton({{confirm}}, variant: .primary) {}
        .disabled(code.count != {{length}})
}

examples.code:
VStack(alignment: .leading, spacing: 12) {
    MonarchOtpPinInput("Verification code", text: $code, length: 6, helper: "Try 123456.")
    MonarchButton("Confirm", variant: .primary) {}
        .disabled(code.count != 6)
}
